FLATS = ["A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab"]
FLAT_TONICS = {"F", "Bb", "Eb", "Ab", "Db", "Gb",
               "d", "g", "c", "f", "bb", "eb"}
STEPS = {"m": 1, "M": 2, "A": 3}


class Scale:
    def __init__(self, tonic):
        self.tonic = tonic[0].upper() + tonic[1:]
        self.names = FLATS if tonic in FLAT_TONICS else SHARPS
        self.start = self.names.index(self.tonic)

    def chromatic(self):
        return [self.names[(self.start + i) % 12] for i in range(12)]

    def interval(self, intervals):
        idx = self.start
        notes = [self.names[idx]]
        for step in intervals:
            idx = (idx + STEPS[step]) % 12
            notes.append(self.names[idx])
        return notes
